parameters.jsCode:
// Read incoming data from Streamlit / Webhook payload
const body = $json.body || $json;
const pest = body.pest || "army_worm";
const language = body.language || "Hindi";

// Dictionary mapping model classes to chemical compositions & dosages
const chemicalDatabase = {
  "army_worm": {
    chemical: "Emamectin Benzoate 5% SG",
    dosage: "4 grams per 10 Liters of water (or 80g/acre)",
    safety: "Apply during early morning or late evening when larvae feed. Ensure thorough spray on whorls and foliage."
  },
  "wheat rust": {
    chemical: "Propiconazole 25% EC",
    dosage: "1 ml per Liter of water (or 200ml/acre)",
    safety: "Spray at the first appearance of pustules on leaves. Repeat after 14 days if rust symptoms persist."
  },
  "wheat smut": {
    chemical: "Tebuconazole 2% DS (Seed Treatment) / Propiconazole",
    dosage: "1.5 grams per kg of seeds (for seed treatment) or 1 ml/L (foliar spray)",
    safety: "Treat seeds prior to sowing or apply systemic fungicide during early boot stage."
  },
  "diseases": {
    chemical: "Mancozeb 75% WP (Broad-Spectrum Fungicide)",
    dosage: "2 grams per Liter of water (or 400g/acre)",
    safety: "Covers general foliar spots and fungal lesions. Spray uniformly over affected crop canopy."
  },
  "Healthy wheat": {
    chemical: "No Chemical Treatment Required",
    dosage: "N/A",
    safety: "Crop is healthy. Maintain proper balanced NPK fertilization, soil moisture, and periodic crop scouting."
  }
};

// Fallback to general broad-spectrum treatment if label mismatch occurs
const selectedInfo = chemicalDatabase[pest] || chemicalDatabase["diseases"];

// Return structured output for the AI translation node
return [{
  json: {
    pest: pest,
    target_language: language,
    chemical: selectedInfo.chemical,
    dosage: selectedInfo.dosage,
    safety: selectedInfo.safety
  }
}];

parameters.prompt:
=You are an agricultural expert assistant. Translate the following chemical treatment instructions into {{ $json.target_language }}. Keep the chemical names in standard English text, but translate the dosage and safety instructions clearly for a farmer.

Chemical: {{ $json.chemical }}
Dosage: {{ $json.dosage }}
Safety Instructions: {{ $json.safety }}
